static JSValue promise_reaction_job(JSContext *ctx, int argc,
                                    JSValueConst *argv)
{
    JSValueConst handler, func;
    JSValue res, res2;
    JSValueConst arg;
    bool is_reject;

    assert(argc == 5);
    handler = argv[2];
    is_reject = JS_ToBool(ctx, argv[3]);
    arg = argv[4];

    promise_trace(ctx, "promise_reaction_job: is_reject=%d\n", is_reject);

    if (JS_IsUndefined(handler)) {
        /* An absent handler forwards an already settled value. In particular,
           a rejection reason is DATA, not a new exception from a handler: its
           existing uncatchable bit must not prevent rejection forwarding. */
        res = js_dup(arg);
    } else {
        res = JS_Call(ctx, handler, JS_UNDEFINED, 1, &arg);
        is_reject = JS_IsException(res);
        if (is_reject) {
            if (unlikely(JS_IsUncatchableError(ctx->rt->current_exception)))
                return JS_EXCEPTION;
            res = JS_GetException(ctx);
        }
    }
    func = argv[is_reject];
    /* as an extension, we support undefined as value to avoid
       creating a dummy promise in the 'await' implementation of async
       functions */
    if (!JS_IsUndefined(func)) {
        res2 = JS_Call(ctx, func, JS_UNDEFINED, 1, vc(&res));
    } else {
        res2 = JS_UNDEFINED;
    }
    JS_FreeValue(ctx, res);

    return res2;
}

static JSValue js_promise_resolve_thenable_job(JSContext *ctx,
                                               int argc, JSValueConst *argv)
{
    JSValueConst promise, thenable, then;
    JSValue args[2] = { JS_UNDEFINED, JS_UNDEFINED };
    JSValue res = JS_UNDEFINED, fatal = JS_UNDEFINED;
    bool has_fatal = false;
    JSRuntime *rt;

    promise_trace(ctx, "js_promise_resolve_thenable_job\n");

    assert(argc == 3);
    promise = argv[0];
    thenable = argv[1];
    then = argv[2];
    if (js_create_resolving_functions(ctx, args, promise) < 0)
        return JS_EXCEPTION;
    rt = ctx->rt;
    if (rt->promise_hook) {
        rt->promise_hook(ctx, JS_PROMISE_HOOK_BEFORE, promise, JS_UNDEFINED,
                         rt->promise_hook_opaque);
        if (JS_HasException(ctx) &&
            JS_IsUncatchableError(ctx->rt->current_exception)) {
            fatal = JS_GetException(ctx);
            goto fatal_cleanup;
        }
    }
    res = JS_Call(ctx, then, thenable, 2, vc(args));
    if (JS_HasException(ctx) &&
        JS_IsUncatchableError(ctx->rt->current_exception)) {
        /* Preserve paired AFTER notification and its existing view of the
           current exception, but retain the first fatal before that hook can
           consume or replace it. This duplicate does not allocate. */
        fatal = js_dup(ctx->rt->current_exception);
        has_fatal = true;
    }
    if (rt->promise_hook) {
        rt->promise_hook(ctx, JS_PROMISE_HOOK_AFTER, promise, JS_UNDEFINED,
                         rt->promise_hook_opaque);
    }
    if (!has_fatal && JS_HasException(ctx) &&
        JS_IsUncatchableError(ctx->rt->current_exception)) {
        fatal = JS_GetException(ctx);
        has_fatal = true;
    }
    if (has_fatal)
        goto fatal_cleanup;
    if (JS_IsException(res)) {
        JSValue error = JS_GetException(ctx);
        res = JS_Call(ctx, args[1], JS_UNDEFINED, 1, vc(&error));
        if (JS_HasException(ctx) &&
            JS_IsUncatchableError(ctx->rt->current_exception)) {
            fatal = JS_GetException(ctx);
            JS_FreeValue(ctx, error);
            goto fatal_cleanup;
        }
        JS_FreeValue(ctx, error);
    }
    JS_FreeValue(ctx, args[0]);
    JS_FreeValue(ctx, args[1]);
    return res;
 fatal_cleanup:
    JS_FreeValue(ctx, res);
    JS_FreeValue(ctx, args[0]);
    JS_FreeValue(ctx, args[1]);
    return JS_Throw(ctx, fatal);
}

pub fn beginInvocation(self: *Engine) void {
    self.requireNoNativeAdmission();
    self.finishJob();
    self.interrupts = 0;
    self.cancelled.store(false, .release);
    if (self.last_error) |message| self.gpa.free(message);
    self.last_error = null;
    if (self.captured_exception) |exception| self.freeValue(exception);
    self.captured_exception = null;
}

pub fn cancel(self: *Engine) void {
    self.cancelled.store(true, .seq_cst);
    if (builtin.os.tag == .linux) {
        const publication = @import("native_child_process_cancel_publication_linux.zig");
        const token = self.native_sync_cancel_token.load(.seq_cst);
        if (token != publication.retiring_token) publication.notify(token);

}

/// Host factory entry: no guest conversion/allocation before preserving a
/// real already-pending event. A prior captured diagnostic is only DATA.
pub fn checkNativeEntry(self: *Engine) !void {
    if (!c.JS_HasException(self.context) and self.currentNativeFatal() == null) return;
    self.native_exception_diagnostics_suppressed += 1;
    defer self.native_exception_diagnostics_suppressed -= 1;
    _ = self.nativeCallbackResult(c.pi_js_undefined());
    self.captureException(self.context);
    return error.JavaScriptException;
}
/// Stack-only current-event retention. No guest value or diagnostic slot
/// can publish into this list; only actual fatal event producers record.
pub const NativeInvocation = struct { previous: ?*NativeInvocation = null, first: ?c.JSValue = null, active: bool = false };
pub fn enterNativeInvocation(self: *Engine, invocation: *NativeInvocation) void {
    std.debug.assert(!invocation.active);
    const inherited = self.currentNativeFatal();
    invocation.* = .{ .previous = self.native_fatal_invocation, .first = if (inherited) |first| c.JS_DupValue(self.context, first) else null, .active = true };
    self.native_fatal_invocation = invocation;
}
fn currentNativeFatal(self: *Engine) ?c.JSValue {
    var cursor = self.native_fatal_invocation;
    while (cursor) |invocation| : (cursor = invocation.previous) if (invocation.first) |first| return first;
    return null;
}
fn recordNativeFatal(self: *Engine, reason: c.JSValue) void {
    const first = self.currentNativeFatal() orelse reason;
    var cursor = self.native_fatal_invocation;
    while (cursor) |invocation| : (cursor = invocation.previous) {
        std.debug.assert(invocation.active);
        if (invocation.first == null) invocation.first = c.JS_DupValue(self.context, first);
    }
}
/// Consumes result exactly once. Pop BEFORE holder cleanup/return so no
/// suspended AF or late finalizer can retain an escaping stack pointer.
pub fn leaveNativeInvocation(self: *Engine, invocation: *NativeInvocation, result: c.JSValue) c.JSValue {
    if (!invocation.active) return result;
    std.debug.assert(self.native_fatal_invocation == invocation);
